import{_ as n,o as t,c as a,a5 as s}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Plan — internal-trends-fetch","description":"","frontmatter":{},"headers":[],"relativePath":"feature/ai-features/internal-trends-fetch/plan.md","filePath":"feature/ai-features/internal-trends-fetch/plan.md"}'),i={name:"feature/ai-features/internal-trends-fetch/plan.md"};function r(o,e,c,l,d,h){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="plan-—-internal-trends-fetch" tabindex="-1">Plan — internal-trends-fetch <a class="header-anchor" href="#plan-—-internal-trends-fetch" aria-label="Permalink to &quot;Plan — internal-trends-fetch&quot;">​</a></h1><h2 id="giai-phap-tong-quan" tabindex="-1">Giải pháp tổng quan <a class="header-anchor" href="#giai-phap-tong-quan" aria-label="Permalink to &quot;Giải pháp tổng quan&quot;">​</a></h2><p>Endpoint đọc-nhanh (read-through cache): GET Redis → hit thì trả ngay, miss thì fetch external source → ghi Redis (TTL) → trả. Tái dùng toàn bộ pattern sẵn có, <strong>không thêm dependency, không thêm config mới.</strong></p><h2 id="luong-du-lieu" tabindex="-1">Luồng dữ liệu <a class="header-anchor" href="#luong-du-lieu" aria-label="Permalink to &quot;Luồng dữ liệu&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /internal/ai/trends/fetch (X-Internal-Key)</span></span>
<span class="line"><span>   │ verify_internal_key (401 nếu sai)</span></span>
<span class="line"><span>   │ validate platform/region (422 nếu sai)</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>GET redis  trends:{platform}:{region}</span></span>
<span class="line"><span>   ├─ hit ──────────────► trả JSON (không gọi external)</span></span>
<span class="line"><span>   └─ miss</span></span>
<span class="line"><span>        │ fetch external (CrawlerRegistry: google_trends | tiktok)</span></span>
<span class="line"><span>        ├─ success ─────► SET redis (ex=ttl) ──► trả envelope</span></span>
<span class="line"><span>        └─ fail</span></span>
<span class="line"><span>             │ re-check redis (có thể concurrent refresh vừa ghi)</span></span>
<span class="line"><span>             ├─ còn cache ► trả cache cũ (không 503)</span></span>
<span class="line"><span>             └─ hết      ► 503</span></span></code></pre></div><h2 id="file-cham-toi" tabindex="-1">File chạm tới <a class="header-anchor" href="#file-cham-toi" aria-label="Permalink to &quot;File chạm tới&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Thay đổi</th></tr></thead><tbody><tr><td><code>brandhub-ai-service/app/api/v1/endpoints/internal_trends.py</code></td><td><strong>Tạo mới</strong> — router + logic endpoint</td></tr><tr><td><code>brandhub-ai-service/app/main.py</code></td><td>Thêm 1 dòng <code>app.include_router(internal_trends.router, prefix=&quot;/internal/ai/trends&quot;, ...)</code></td></tr><tr><td><code>brandhub-ai-service/tests/unit/api/test_internal_trends_fetch.py</code></td><td><strong>Tạo mới</strong> — pytest</td></tr><tr><td><code>brandhub-infrastructure/docs/feature/ai-features/internal-trends-fetch/*</code></td><td>4 doc</td></tr></tbody></table><p><strong>Không sửa</strong>: <code>config.py</code>, <code>clients.py</code>, <code>security.py</code>, <code>router.py</code> — tái dùng nguyên trạng.</p><h2 id="quyet-đinh-ky-thuat" tabindex="-1">Quyết định kỹ thuật <a class="header-anchor" href="#quyet-đinh-ky-thuat" aria-label="Permalink to &quot;Quyết định kỹ thuật&quot;">​</a></h2><ol><li><p><strong>Auth</strong>: <code>verify_internal_key</code> (<code>X-Internal-Key</code> vs <code>settings.internal_service_key</code>) — dùng <code>dependencies=[Depends(verify_internal_key)]</code> như các endpoint <code>/crawl</code>, <code>/normalize</code> hiện có.</p></li><li><p><strong>Redis client</strong>: <code>get_redis_client()</code> (decode_responses=True) — phù hợp lưu/đọc JSON string. Không dùng <code>get_trend_redis_client()</code> (bytes mode, dành cho scheduler).</p></li><li><p><strong>Redis key + TTL</strong>: key <code>trends:{platform}:{region}</code> (đúng spec). Giá trị = JSON envelope <code>{trends, cachedAt, ttlSeconds}</code>. TTL = <code>settings.live_cache_ttl_seconds</code> (đã có sẵn, = <code>crawl_interval_hours * 3600</code>, mặc định 21600s = 6h, nằm trong khoảng 1–6h của spec).</p></li><li><p><strong>External source mapping</strong>: Google Trends là tín hiệu mặc định (platform-agnostic); TIKTOK dùng trending feed riêng:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">_SOURCE_BY_PLATFORM</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;TIKTOK&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tiktok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># còn lại -&gt; &quot;google_trends&quot;</span></span></code></pre></div><p>Gọi qua <code>CrawlerRegistry.get_crawler(source).crawl(target=region, limit=20)</code>. Mock hiện tại trả <code>RawPostItem</code> → map thành <code>{topic, score, relatedHashtags}</code>:</p><ul><li><code>topic</code>: keyword Google Trends (strip prefix) / hashtag đầu / raw_text 60 ký tự.</li><li><code>score</code>: <code>search_volume</code> → <code>views</code> → <code>likes</code> → 0.</li><li><code>relatedHashtags</code>: <code>item.hashtags</code> bỏ <code>#</code>.</li></ul></li><li><p><strong>Fallback stale-not-503</strong>: khi external fail, re-check Redis 1 lần trước khi 503 — phủ trường hợp concurrent refresh vừa ghi + giữ cache cũ không bị xoá.</p></li><li><p><strong>Background job (bỏ, có lý do)</strong>: spec nói &quot;background job refreshes every 1–6 hours&quot;. Không implement standalone warm job vì:</p><ul><li>Không có danh sách (platform, region) nào để warm (spec không liệt kê).</li><li>On-demand refresh + TTL cho consumer đúng hành vi (luôn có fresh-or-cached data).</li><li><code>ponytail:</code> thêm APScheduler warm job khi có danh sách region cần làm nóng + cache-miss latency đo được là vấn đề thật.</li></ul></li></ol><h2 id="rui-ro" tabindex="-1">Rủi ro <a class="header-anchor" href="#rui-ro" aria-label="Permalink to &quot;Rủi ro&quot;">​</a></h2><ul><li>Mock crawler không phân biệt region (trả cùng keyword) → v1 chấp nhận, thay bằng API thật sau.</li><li>Fetch external trùng khi concurrent miss → chấp nhận v1 (xem Edge Cases).</li></ul>`,12)])])}const u=n(i,[["render",r]]);export{g as __pageData,u as default};
